// Why Code: transpose the key|value Settings tab into one object.
const rows = $input.all().map((i) => i.json);
const cfg = {};
for (const r of rows) {
  const k = String(r.key ?? '').trim();
  if (k) cfg[k] = r.value ?? '';
}
return [{ json: cfg }];

// Why Code: group-by-staff with interval math has no native node equivalent.
const tz = $('Pivot Settings').first().json.timezone || 'Africa/Lagos';
const now = DateTime.now().setZone(tz);
const prev = now.minus({ months: 1 });
const ym = prev.toFormat('yyyy-MM');
const rows = $('Read Rota').all().map((i) => i.json);
const sums = new Map();
for (const r of rows) {
  if (String(r.status).toUpperCase() !== 'CONFIRMED') continue;
  const d = DateTime.fromFormat(String(r.date), 'yyyy-MM-dd', { zone: tz });
  if (!d.isValid || d.toFormat('yyyy-MM') !== ym) continue;
  const s = DateTime.fromFormat(String(r.date) + ' ' + String(r.startTime), 'yyyy-MM-dd HH:mm', { zone: tz });
  let e = DateTime.fromFormat(String(r.date) + ' ' + String(r.endTime), 'yyyy-MM-dd HH:mm', { zone: tz });
  if (e <= s) e = e.plus({ days: 1 });
  const hrs = e.diff(s, 'minutes').minutes / 60;
  const k = String(r.staffId || r.staffName || r.email);
  if (!sums.has(k)) sums.set(k, { month: ym, staffId: r.staffId || '', staffName: r.staffName || '', email: r.email || '', shiftsConfirmed: 0, hours: 0 });
  const agg = sums.get(k); agg.shiftsConfirmed += 1; agg.hours += hrs;
}
const items = [...sums.values()].map((v) => ({ json: {
  month: v.month, staffId: v.staffId, staffName: v.staffName, email: v.email,
  shiftsConfirmed: v.shiftsConfirmed, hoursWorked: Number(v.hours.toFixed(2)),
  generatedAt: now.toISO(),
} }));
return items;

