// Why Code: supervisor table report needs the same aggregation, rendered as text; no native node formats tables.
const cfg = $('Pivot Settings').first().json;
const facility = cfg.facilityName || 'the facility';
const tz = cfg.timezone || 'Africa/Lagos';
const now = DateTime.now().setZone(tz);
const prev = now.minus({ months: 1 });
const ym = prev.toFormat('yyyy-MM');
const monthLabel = prev.toFormat('MMMM yyyy');
const rows = $('Read Rota').all().map((i) => i.json);
const sums = new Map();
let totalShifts = 0, totalHours = 0;
for (const r of rows) {
  if (String(r.status).toUpperCase() !== 'CONFIRMED') continue;
  const d = DateTime.fromFormat(String(r.date), 'yyyy-MM-dd', { zone: tz });
  if (!d.isValid || d.toFormat('yyyy-MM') !== ym) continue;
  const s = DateTime.fromFormat(String(r.date) + ' ' + String(r.startTime), 'yyyy-MM-dd HH:mm', { zone: tz });
  let e = DateTime.fromFormat(String(r.date) + ' ' + String(r.endTime), 'yyyy-MM-dd HH:mm', { zone: tz });
  if (e <= s) e = e.plus({ days: 1 });
  const hrs = e.diff(s, 'minutes').minutes / 60;
  const k = String(r.staffId || r.staffName || r.email);
  if (!sums.has(k)) sums.set(k, { name: r.staffName || k, shifts: 0, hours: 0 });
  const agg = sums.get(k); agg.shifts += 1; agg.hours += hrs;
  totalShifts += 1; totalHours += hrs;
}
const line = '-'.repeat(56);
const body = [
  'ShiftHub - Monthly Hours Summary',
  '',
  'Facility: ' + facility,
  'Month:    ' + monthLabel + ' (' + ym + ')',
  'Generated: ' + now.toFormat('yyyy-MM-dd HH:mm'),
  '',
  line,
  'Staff'.padEnd(34) + 'Shifts'.padStart(8) + 'Hours'.padStart(12),
  line,
];
for (const v of [...sums.values()].sort((a, b) => b.hours - a.hours)) {
  body.push(String(v.name).padEnd(34).slice(0, 33) + String(v.shifts).padStart(8) + v.hours.toFixed(1).padStart(12));
}
body.push(line);
body.push('TOTAL'.padEnd(34) + String(totalShifts).padStart(8) + totalHours.toFixed(1).padStart(12));
body.push(line);
body.push('');
body.push('Per-staff hours are also stored in the MonthlySummary tab and emailed to each staff member where sendStaffCopies = yes.');
return [{ json: {
  supervisorEmail: cfg.supervisorEmail,
  subject: '[ShiftHub] Monthly hours summary - ' + monthLabel,
  message: body.join('\n'),
} }];
